        cout << "empty\n";
        return;
    }
    vector<string> out;
    vector<TreeNode*> queue = {root};
    size_t head = 0;
    while (head < queue.size()) {
        TreeNode* node = queue[head++];
        if (node == nullptr) {
            out.push_back("N");
        } else {
            out.push_back(to_string(node->val));
            queue.push_back(node->left);
            queue.push_back(node->right);
        }
